// C# 12 / .NET 8 - Zero-allocation Value Type vs Reference Type trong High-Throughput Trading
using System;

// 1. Reference Type: Cấp phát trên Managed Heap, tạo áp lực lên Gen 0 GC
public sealed class OrderReference
{
    public long OrderId { get; init; }
    public decimal Price { get; init; }
    public int Quantity { get; init; }
}

// 2. Value Type: Readonly Struct cấp phát trực tiếp trên Stack hoặc inline trong mảng
public readonly struct OrderValue(long orderId, decimal price, int quantity)
{
    public long OrderId { get; } = orderId;
    public decimal Price { get; } = price;
    public int Quantity { get; } = quantity;

    // 'in' modifier truyền tham chiếu bất biến (read-only reference) tránh sao chép struct 24-byte
    public static decimal CalculateNotional(in OrderValue order) => order.Price * order.Quantity;
}

public static class ExecutionEngine
{
    public static void ProcessBatch()
    {
        // Heap allocation (tạo con trỏ 8 bytes + 16 bytes header + 24 bytes payload = 48 bytes)
        var refOrder = new OrderReference { OrderId = 1001, Price = 150.25m, Quantity = 100 };

        // Stack allocation (thuần túy 24 bytes, giải phóng ngay khi stack unwinding, 0 byte GC)
        var valOrder = new OrderValue(1002, 200.50m, 50);
        decimal notional = OrderValue.CalculateNotional(in valOrder);

        Console.WriteLine($"Ref Order: {refOrder.OrderId}, Val Order Notional: {notional}");
    }
}

// C# 12 / .NET 8 - Xử lý Nullable<T> an toàn trong Transaction Settlement Engine
using System;

public readonly record struct SettlementSummary(
    long TransactionId,
