// C# 12 / .NET 8 - Zero-allocation String Mutation qua string.Create
using System;

public static class SafeTokenFormatter
{
    // Biến đổi chuỗi mà vẫn đảm bảo tính Immutability ra bên ngoài mà không cấp phát trung gian
    public static string MaskCreditCard(ReadOnlySpan<char> pan)
    {
        if (pan.Length != 16)
            throw new ArgumentException("Invalid PAN length", nameof(pan));

        // string.Create cho phép ghi trực tiếp vào buffer của chuỗi mới trước khi freeze immutability
        return string.Create(19, pan.ToArray(), (buffer, state) =>
        {
            var source = state.AsSpan();
            // Format: 1234-****-****-5678
            source[..4].CopyTo(buffer[..4]);
            buffer[4] = '-';
            buffer[5..9].Fill('*');
            buffer[9] = '-';
            buffer[10..14].Fill('*');
            buffer[14] = '-';
            source[12..16].CopyTo(buffer[15..19]);
        });
    }
}

// C# 12 / .NET 8 - Tận dụng tối ưu hóa phần cứng của CLR JIT Tier 1 Vectorization
using System;
using System.Numerics;
using System.Runtime.Intrinsics;
using System.Runtime.Intrinsics.X86;

public static class ClrPerformanceEngine
{
    // CLR RyuJIT tự động nhận diện và sinh mã máy SIMD phần cứng nếu CPU hỗ trợ AVX2
    public static void VectorizedSum(ReadOnlySpan<float> input, Span<float> output, float multiplier)
    {
        int i = 0;
        int vectorSize = Vector<float>.Count;
        var factorVector = new Vector<float>(multiplier);

        // JIT sẽ biến đổi vòng lặp này thành tập lệnh SIMD native trên CPU x64/ARM64
        for (; i <= input.Length - vectorSize; i += vectorSize)
        {
            var dataVector = new Vector<float>(input.Slice(i, vectorSize));
            (dataVector * factorVector).CopyTo(output.Slice(i, vectorSize));
        }

        // Xử lý các phần tử dư thừa còn lại
        for (; i < input.Length; i++)
        {
            output[i] = input[i] * multiplier;
        }
    }
}

// C# 12 / .NET 8 - Chẩn đoán và quan sát thông số GC trong Enterprise Microservice
using System;

public static class GcMetricsDiagnostics
{
    public static void PrintGcHealthReport()
    {
        // Thu thập thông tin chi tiết từ GC Engine trong .NET 8
        GCMemoryInfo memInfo = GC.GetGCMemoryInfo();

        Console.WriteLine($"Heap Size: {memInfo.HeapSizeBytes / (1024 * 1024)} MB");
        Console.WriteLine($"Fragmented Bytes: {memInfo.FragmentedBytes / 1024} KB");
        Console.WriteLine($"Memory Load: {memInfo.MemoryLoadBytes / (1024 * 1024)} MB");
        Console.WriteLine($"Gen 0 Collections: {GC.CollectionCount(0)}");
        Console.WriteLine($"Gen 1 Collections: {GC.CollectionCount(1)}");
        Console.WriteLine($"Gen 2 Collections: {GC.CollectionCount(2)}");
        Console.WriteLine($"Last GC Pause Duration: {memInfo.PauseDurations[0].TotalMilliseconds} ms");
    }
}

// C# 12 / .NET 8 - Enterprise Configuration: Const vs Static Readonly vs Init-only
using System;

public sealed class GatewayConfiguration
{
    // 1. Const: Nhúng cứng vào IL lúc compile. Phù hợp với toán học, quy chuẩn bất biến tuyệt đối
    public const string ProtocolVersion = "v2.1"; 

    // 2. Static Readonly: Khởi tạo động lúc Runtime, an toàn khi update DLL mà không cần recompile caller
    public static readonly TimeSpan DefaultTimeout = TimeSpan.FromSeconds(
        int.TryParse(Environment.GetEnvironmentVariable("GATEWAY_TIMEOUT_SEC"), out var s) ? s : 30
    );

    // 3. Instance Readonly / Init-only: Bất biến cho từng instance cụ thể sau khi khởi tạo
    public string EndpointUrl { get; init; }

    public GatewayConfiguration(string endpointUrl)
    {
        EndpointUrl = endpointUrl ?? throw new ArgumentNullException(nameof(endpointUrl));
    }
}

// C# 12 / .NET 8 - Tối ưu hóa StringBuilder có Pre-allocated Capacity
using System;
using System.Collections.Generic;
using System.Text;

public static class AuditLogExporter
{
    public readonly record struct AuditEntry(long Id, string Action, DateTime Timestamp);

    public static string ExportToCsv(IReadOnlyList<AuditEntry> entries)
    {
        if (entries.Count == 0) return string.Empty;

        // Khởi tạo Capacity xấp xỉ (~60 ký tự mỗi dòng) để tránh reallocation các chunks
        int estimatedCapacity = entries.Count * 60;
        var sb = new StringBuilder(estimatedCapacity);

        sb.AppendLine("Id,Action,Timestamp");
        foreach (var entry in entries)
        {
            // Append trực tiếp không tạo string trung gian thông qua ISpanFormattable trong .NET 8
            sb.Append(entry.Id)
              .Append(',')
              .Append(entry.Action)
              .Append(',')
              .AppendFormat("{0:yyyy-MM-ddTHH:mm:ssZ}", entry.Timestamp)
              .AppendLine();
        }

        return sb.ToString();
    }
}

// C# 12 / .NET 8 - Chuẩn mực Implement Value Equality cho DDD Value Object
using System;

public sealed class CurrencyAmount : IEquatable<CurrencyAmount>
{
    public decimal Amount { get; }
    public string CurrencyCode { get; }

    public CurrencyAmount(decimal amount, string currencyCode)
    {
        Amount = amount;
        CurrencyCode = currencyCode?.ToUpperInvariant() ?? throw new ArgumentNullException(nameof(currencyCode));
    }

    public bool Equals(CurrencyAmount? other)
    {
        if (other is null) return false;
        if (ReferenceEquals(this, other)) return true;
        return Amount == other.Amount && CurrencyCode == other.CurrencyCode;
    }

    public override bool Equals(object? obj) => obj is CurrencyAmount other && Equals(other);

    // Bắt buộc override GetHashCode khi override Equals để dùng trong Dictionary/HashSet
    public override int GetHashCode() => HashCode.Combine(Amount, CurrencyCode);

    public static bool operator ==(CurrencyAmount? left, CurrencyAmount? right) => Equals(left, right);
    public static bool operator !=(CurrencyAmount? left, CurrencyAmount? right) => !Equals(left, right);
}

// C# 12 / .NET 8 - High-performance Vector Struct vs Domain Entity Class
using System;

// 1. Struct: Nhỏ gọn, 12 bytes, contiguous memory, 0 byte GC allocation
public readonly struct Vector3D(float x, float y, float z)
{
    public float X { get; } = x;
    public float Y { get; } = y;
    public float Z { get; } = z;

