// C# 12 / .NET 8 - Sức mạnh hiệu năng của Collection Expressions
using System;
using System.Collections.Generic;

public static class CollectionExpressionDemo
{
    public static void ProcessCollections()
    {
        // 1. Zero-Allocation: Trỏ trực tiếp vào dữ liệu tĩnh trong Assembly PE Header
        ReadOnlySpan<int> staticLookup = [10, 20, 30, 40, 50];

        // 2. Tự động tính trước Capacity chính xác = 6, không bao giờ bị reallocate
        int[] initial = [1, 2];
        int[] tail = [5, 6];
        List<int> combined = [..initial, 3, 4, ..tail]; // Sử dụng Spread Operator

        // 3. Khởi tạo Dictionary / Immutable collections đồng nhất
        HashSet<string> uniqueCodes = ["USD", "EUR", "JPY"];

        Console.WriteLine($"Span Length: {staticLookup.Length}, Combined Capacity: {combined.Capacity}");
    }
}

// C# 12 / .NET 8 - Event Processing sử dụng Modern Pattern Matching thay vì 'as'
using System;

public abstract record IntegrationEvent(Guid Id, DateTime Timestamp);
public sealed record PaymentCompletedEvent(Guid Id, DateTime Timestamp, decimal Amount) : IntegrationEvent(Id, Timestamp);
public sealed record OrderCancelledEvent(Guid Id, DateTime Timestamp, string Reason) : IntegrationEvent(Id, Timestamp);

public static class EventRouter
{
    public static void RouteEvent(IntegrationEvent @event)
    {
        // Khuyến nghị hiện đại: Pattern matching với 'is' trực quan, an toàn, 0 overhead
        switch (@event)
        {
            case PaymentCompletedEvent payment:
                Console.WriteLine($"Processing payment: {payment.Amount:C}");
                break;
            case OrderCancelledEvent { Reason: "FraudDetected" } cancelled:
                Console.WriteLine($"Urgent: Order {cancelled.Id} cancelled due to fraud!");
                break;
            default:
                Console.WriteLine("Unhandled event type");
                break;
        }
    }
}

// C# 12 / .NET 8 - High-performance Native Interop với Source Generated P/Invoke
using System;
using System.Runtime.InteropServices;

public static partial class NativeCryptoWrapper
{
    // Sử dụng [LibraryImport] trong .NET 8 thay cho [DllImport] cũ để sinh mã CIL cực nhanh lúc compile
    [LibraryImport("kernel32.dll", EntryPoint = "GetCurrentProcessId")]
    [UnmanagedCallConv(CallConvs = [typeof(System.Runtime.CompilerServices.CallConvStdcall)])]
    public static partial uint GetNativeProcessId();

    public static void ExecuteUnmanagedAllocation()
    {
        // Cấp phát unmanaged memory trực tiếp (không chịu sự quản lý của GC)
        IntPtr unmanagedMemory = Marshal.AllocHGlobal(1024);
        try
        {
            Console.WriteLine($"Allocated 1KB Unmanaged Memory at: 0x{unmanagedMemory:X}");
            Console.WriteLine($"Current Process ID from Win32: {GetNativeProcessId()}");
        }
        finally
        {
            // BẮT BUỘC giải phóng thủ công, nếu quên sẽ gây rò rỉ RAM vĩnh viễn (Memory Leak)
            Marshal.FreeHGlobal(unmanagedMemory);
        }
    }
}

// C# 12 / .NET 8 - Zero-allocation ValueTuple và Custom Class Deconstruction
using System;

public readonly record struct GatewayResponse(int Code, string Status, TimeSpan Latency);

public sealed class OrderAggregate
{
    public Guid Id { get; init; } = Guid.NewGuid();
    public decimal TotalAmount { get; init; }
    public string Currency { get; init; } = "USD";

    // Triển khai Deconstruct method để hỗ trợ cú pháp Deconstruction đa hình
    public void Deconstruct(out Guid id, out decimal amount, out string currency)
    {
        id = Id;
        amount = TotalAmount;
        currency = Currency;
    }
}

public static class TupleDemo
{
    public static (bool Success, string ErrorMessage) ValidateOrder(decimal amount)
    {
        if (amount <= 0) return (false, "Amount must be positive");
        return (true, string.Empty); // Zero heap allocation
    }

    public static void Run()
    {
        // 1. ValueTuple Deconstruction kết hợp Discard operator (_)
        var (isOk, _) = ValidateOrder(100.5m);

        // 2. Custom Object Deconstruction
        var order = new OrderAggregate { TotalAmount = 500.0m };
        var (orderId, total, curr) = order;

        Console.WriteLine($"Order {orderId}: {total} {curr}, Valid: {isOk}");
    }
}

// C# 12 / .NET 8 - Kiến trúc Pipeline chuẩn mực cho Enterprise Web API
using System;
using Microsoft.AspNetCore.Builder;
using Microsoft.AspNetCore.Http;
using Microsoft.Extensions.Hosting;

var builder = WebApplication.CreateBuilder(args);
var app = builder.Build();

// 1. Luôn đặt ExceptionHandler & Security Headers ở đầu để bao bọc toàn bộ lỗi phát sinh phía sau
app.Use(async (context, next) =>
{
    context.Response.Headers.Append("X-Content-Type-Options", "nosniff");
    await next(context); // Chuyển tiếp request vào trong
    // Xử lý Response khi quay ngược ra ngoài tại đây
});

// 2. Branching Pipeline với Map: Chỉ áp dụng cho path /health
app.Map("/health", healthApp =>
{
    // Terminal Middleware với Run: Ngắt luôn pipeline, không đi sâu hơn
    healthApp.Run(async context =>
    {
        context.Response.StatusCode = 200;
        await context.Response.WriteAsync("{\"status\":\"healthy\"}");
    });
});

// 3. Đúng chuẩn thứ tự: Routing -> Cors -> AuthN -> AuthZ -> Endpoints
app.UseRouting();
// app.UseCors();
// app.UseAuthentication();
// app.UseAuthorization();

app.MapGet("/api/orders", () => Results.Ok(new { Message = "Authenticated Orders" }));

app.Run();

// C# 12 / .NET 8 - Production-grade BackgroundService với Graceful Shutdown và Scoped DI
using System;
using System.Threading;
using System.Threading.Tasks;
using Microsoft.Extensions.DependencyInjection;
using Microsoft.Extensions.Hosting;
using Microsoft.Extensions.Logging;

public sealed class KafkaOrderConsumer(
    IServiceScopeFactory scopeFactory,
    ILogger<KafkaOrderConsumer> logger) : BackgroundService
{
    protected override async Task ExecuteAsync(CancellationToken stoppingToken)
    {
        logger.LogInformation("Order Consumer Service started successfully.");

        // Luôn luôn kiểm tra IsCancellationRequested để hỗ trợ Graceful Shutdown
        while (!stoppingToken.IsCancellationRequested)
        {
            try
            {
                // BackgroundService là Singleton, bắt buộc tạo Scope thủ công để dùng Scoped Service (như DbContext)
                using (var scope = scopeFactory.CreateScope())
                {
                    // var db = scope.ServiceProvider.GetRequiredService<AppDbContext>();
                    // Giả lập đọc và xử lý message
                    await Task.Delay(1000, stoppingToken);
                }
            }
            catch (OperationCanceledException) when (stoppingToken.IsCancellationRequested)
            {
                // Bỏ qua exception khi nhận tín hiệu shutdown bình thường
                break;
            }
            catch (Exception ex)
            {
                logger.LogError(ex, "Unhandled error in Kafka consumer loop");
            }
        }

        logger.LogInformation("Order Consumer flushed offsets and stopped cleanly.");
    }
}

