// C# 12 / .NET 8 - Clean Architecture với Nullable Reference Types
#nullable enable
using System;

public sealed class UserRegistrationService
{
    // Non-nullable properties: Bắt buộc phải có giá trị hợp lệ sau khi constructor kết thúc
    public string Username { get; init; }
    public string? MiddleName { get; init; } // Nullable: Giá trị tùy chọn

    public UserRegistrationService(string username, string? middleName = null)
    {
        // ArgumentNullException.ThrowIfNull là guard-clause runtime bắt buộc trong .NET 8
        ArgumentNullException.ThrowIfNull(username);
        Username = username;
        MiddleName = middleName;
    }

    public void ProcessInternalLegacyData(object? rawPayload)
    {
        // Dùng Null-forgiving operator (!) khi biết chắc chắn dữ liệu không null
        // nhưng Roslyn static analyzer không thể suy diễn được
        string guaranteedNonNull = rawPayload!.ToString()!;
        Console.WriteLine($"Payload: {guaranteedNonNull}");
    }
}

// C# 12 / .NET 8 - Cấu trúc tự sinh an toàn của EF Core Migration với Up và Down logic
using Microsoft.EntityFrameworkCore.Migrations;

public partial class AddLoyaltyPointsToCustomer : Migration
{
    protected override void Up(MigrationBuilder migrationBuilder)
    {
        // Thêm cột an toàn có giá trị mặc định để không gây lock bảng lâu
        migrationBuilder.AddColumn<int>(
            name: "LoyaltyPoints",
            table: "Customers",
            type: "int",
            nullable: false,
            defaultValue: 0);
    }

    protected override void Down(MigrationBuilder migrationBuilder)
    {
        // Khi rollback: EF Core sẽ thực thi phương thức Down này để khôi phục schema cũ
        migrationBuilder.DropColumn(
            name: "LoyaltyPoints",
            table: "Customers");
    }
}

// C# 12 / .NET 8 - Đăng ký DbContext chuẩn mực và Tối ưu hiệu năng cao với DbContextPool
using Microsoft.EntityFrameworkCore;
using Microsoft.Extensions.DependencyInjection;
using Microsoft.Extensions.Hosting;

var builder = Host.CreateApplicationBuilder();

// 1. Chuẩn mực: Đăng ký Scoped (mặc định của AddDbContext)
builder.Services.AddDbContext<AppDbContext>(options =>
    options.UseSqlServer("Server=.;Database=FinanceDb;Trusted_Connection=True;"));

// 2. High-throughput Enterprise: Sử dụng AddDbContextPool để tái sử dụng instance DbContext
// Giảm thiểu cấp phát rác trên GC mà vẫn đảm bảo an toàn Scoped theo từng Request
builder.Services.AddDbContextPool<AppDbContext>(options =>
    options.UseSqlServer("Server=.;Database=FinanceDb;Trusted_Connection=True;"), poolSize: 1024);

