// C# 12 / .NET 8 - Projection sang C# 12 Record DTO trong Minimal API
using System;
using System.Linq;
using System.Threading.Tasks;
using Microsoft.EntityFrameworkCore;

public readonly record struct CustomerResponseDto(Guid Id, string FullName, decimal CurrentBalance);

public static class CustomerEndpoints
{
    public static async Task<IResult> GetTopCustomers(AppDbContext db)
    {
        // EF Core dịch chính xác sang: SELECT [c].[Id], [c].[FullName], [c].[Balance] FROM [Customers] ...
        // Hoàn toàn không load PasswordHash, InternalNotes hay AuditLogs
        var topCustomers = await db.Customers
            .AsNoTracking()
            .Where(c => c.IsActive)
            .OrderByDescending(c => c.Balance)
            .Take(10)
            .Select(c => new CustomerResponseDto(c.Id, c.FullName, c.Balance))
            .ToListAsync();

        return Results.Ok(topCustomers);
    }
}

// C# 12 / .NET 8 - Tùy biến chuẩn hóa phản hồi ProblemDetails với [ApiController]
using System.ComponentModel.DataAnnotations;
using Microsoft.AspNetCore.Builder;
using Microsoft.AspNetCore.Mvc;
using Microsoft.Extensions.DependencyInjection;

var builder = WebApplication.CreateBuilder(args);
builder.Services.AddControllers()
    .ConfigureApiBehaviorOptions(options =>
    {
        // Tùy biến cấu trúc phản hồi tự động chuẩn Enterprise
        options.InvalidModelStateResponseFactory = context =>
        {
            var problemDetails = new ValidationProblemDetails(context.ModelState)
            {
                Type = "https://api.mycompany.com/errors/validation",
                Title = "Dữ liệu đầu vào không hợp lệ.",
                Status = StatusCodes.Status400BadRequest,
                Instance = context.HttpContext.Request.Path
            };
            return new BadRequestObjectResult(problemDetails);
        };
    });

var app = builder.Build();
app.MapControllers();

