// C# 12 / .NET 8 - Template Method Pattern với Abstract Class trong Payment Gateway
using System;
using System.Threading.Tasks;

public abstract class BasePaymentGateway
{
    protected readonly string MerchantId;

    protected BasePaymentGateway(string merchantId)
    {
        MerchantId = merchantId ?? throw new ArgumentNullException(nameof(merchantId));
    }

    // Template Method: Định nghĩa khung xương thuật toán bất biến
    public async Task<bool> ProcessPaymentAsync(decimal amount, string orderId)
    {
        Console.WriteLine($"[AUDIT] Bắt đầu giao dịch {orderId} số tiền {amount:C}");

        // Gọi phương thức trừu tượng để lớp con triển khai thuật toán mã hóa riêng
        string signature = GenerateSignature(orderId, amount);

        bool isSuccess = await ExecuteHttpCallAsync(orderId, amount, signature);

        Console.WriteLine($"[AUDIT] Kết thúc giao dịch {orderId}. Kết quả: {isSuccess}");
        return isSuccess;
    }

    protected abstract string GenerateSignature(string orderId, decimal amount);
    protected abstract Task<bool> ExecuteHttpCallAsync(string orderId, decimal amount, string signature);
}

public sealed class VnpayGateway(string merchantId) : BasePaymentGateway(merchantId)
{
    protected override string GenerateSignature(string orderId, decimal amount) =>
        $"VNPAY-HMAC-SHA512-{MerchantId}-{orderId}-{amount}";

    protected override Task<bool> ExecuteHttpCallAsync(string orderId, decimal amount, string signature) =>
        Task.FromResult(true); // Giả lập gửi HTTP request
}

