// C# 12 / .NET 8 - High-performance Generic Ring Buffer với Constraints
using System;

public sealed class RingBuffer<T>(int capacity)
{
    private readonly T[] _buffer = new T[capacity];
    private int _head;
    private int _tail;

    // Zero-allocation, hoàn toàn không có boxing nếu T là struct
    public void Enqueue(T item)
    {
        _buffer[_tail] = item;
        _tail = (_tail + 1) % _buffer.Length;
    }

    public T Dequeue()
    {
        T item = _buffer[_head];
        _buffer[_head] = default!; // Xóa tham chiếu để GC dọn dẹp nếu là reference type
        _head = (_head + 1) % _buffer.Length;
        return item;
    }
}

