public static class TransactionQueryService
{
    public static async Task<List<TransactionDto>> GetPagedTransactionsAsync(
        IQueryable<TransactionEntity> sourceQuery, // Giữ nguyên IQueryable để tối ưu SQL
        int pageIndex,
        int pageSize)
    {
        // Mọi phép toán Filter, Sort, Skip, Take được dịch 100% thành SQL OFFSET-FETCH trên SQL Server
        return await sourceQuery
            .AsNoTracking()
            .Where(t => t.Status == "SUCCESS")
