            .Skip((pageIndex - 1) * pageSize)
            .Take(pageSize)
            .Select(t => new TransactionDto(t.Id, t.Amount, t.CreatedAtUtc))
            .ToListAsync(); // Chỉ tại thời điểm này SQL mới được gửi tới DB Server
