// C# 12 / .NET 8 - Đối chiếu Query Syntax vs Method Syntax với mệnh đề 'let'
using System;
using System.Collections.Generic;
using System.Linq;

public static class LinqSyntaxComparison
{
    public sealed record Employee(string Name, decimal BaseSalary, decimal Bonus);

    public static void Compare(List<Employee> employees)
    {
        // 1. Query Syntax: Cực kỳ trực quan khi có mệnh đề 'let' tính toán trung gian
        var highEarnersQuery = 
            from e in employees
            let totalIncome = e.BaseSalary + e.Bonus // Transparent Identifier
            where totalIncome > 100_000
            orderby totalIncome descending
            select new { e.Name, Income = totalIncome };

        // 2. Method Syntax: Cú pháp compiler thực sự biên dịch ra (phải dùng anonymous type trung gian)
        var highEarnersMethod = employees
            .Select(e => new { e, totalIncome = e.BaseSalary + e.Bonus })
            .Where(x => x.totalIncome > 100_000)
            .OrderByDescending(x => x.totalIncome)
            .Select(x => new { x.e.Name, Income = x.totalIncome });

        // 3. Những toán tử CHỈ CÓ trong Method Syntax: Skip, Take, Chunk, DistinctBy
        var top3 = highEarnersMethod.Take(3).ToList();
    }
}

