// C# 12 / .NET 8 - Xử lý Race Condition với SemaphoreSlim và Interlocked
using System;
using System.Threading;
using System.Threading.Tasks;

public sealed class InventoryStockManager
{
    private int _atomicCounter;
    private int _availableStock = 1;
    private readonly SemaphoreSlim _asyncLock = new(1, 1); // Mutex cho mã async

    // 1. Lock-free Atomic Counter siêu nhanh bằng thanh ghi CPU
    public void IncrementMetrics() => Interlocked.Increment(ref _atomicCounter);

    // 2. Ngăn chặn Race Condition trong tác vụ bất đồng bộ
    public async Task<bool> TryDeductStockAsync(string userId)
    {
        // Chờ nhận quyền truy cập an toàn mà không block OS thread
        await _asyncLock.WaitAsync();
        try
        {
            // Critical Section: Đảm bảo chỉ duy nhất 1 thread được kiểm tra và trừ tồn kho
            if (_availableStock > 0)
            {
                await Task.Delay(50); // Giả lập I/O trừ kho
                _availableStock--;
                Console.WriteLine($"User {userId} mua thành công! Tồn kho còn: {_availableStock}");
                return true;
            }

            Console.WriteLine($"User {userId} mua thất bại. Hết hàng!");
            return false;
        }
        finally
        {
            _asyncLock.Release(); // Bắt buộc giải phóng lock trong khối finally
        }
    }
}

