// C# 12 / .NET 8 - Cooperative Cancellation với LinkedTokenSource và Timeout
using System;
using System.IO;
using System.Threading;
using System.Threading.Tasks;

public static class ResilientFileProcessor
{
    public static async Task ProcessLargeFileAsync(
        string filePath, 
        CancellationToken userToken)
    {
        // Tạo CTS tự động ngắt nếu vượt quá 30 giây (Timeout)
        using var timeoutCts = new CancellationTokenSource(TimeSpan.FromSeconds(30));

        // Tạo Linked Token kết hợp cả yêu cầu hủy từ User và Timeout hệ thống
        using var linkedCts = CancellationTokenSource.CreateLinkedTokenSource(userToken, timeoutCts.Token);
        var token = linkedCts.Token;

        try
        {
            using var reader = new StreamReader(filePath);
            string? line;
            int count = 0;

            while ((line = await reader.ReadLineAsync(token)) != null)
            {
                // Kiểm tra token trước mỗi bước tính toán nặng
                token.ThrowIfCancellationRequested();

                count++;
                // Giả lập xử lý nghiệp vụ
            }
            Console.WriteLine($"Đã xử lý thành công {count} dòng.");
        }
        catch (OperationCanceledException) when (userToken.IsCancellationRequested)
        {
            Console.WriteLine("[CANCELLED] Tác vụ đã bị người dùng chủ động hủy bỏ an toàn.");
        }
