        }
    }
}

// C# 12 / .NET 8 - Đối chiếu Eager Loading an toàn vs Cạm bẫy của Lazy Loading
using System;
using System.Collections.Generic;
using System.Linq;
using System.Threading.Tasks;
using Microsoft.EntityFrameworkCore;

public static class LoadingStrategyComparison
{
    // 1. EAGER LOADING: Chuẩn mực Enterprise - 1 câu query SQL duy nhất (JOIN)
    public static async Task LoadWithEagerLoadingAsync(AppDbContext db)
    {
        var invoices = await db.Invoices
            .AsNoTracking()
            .Include(i => i.Items)
            .ThenInclude(item => item.Product)
            .ToListAsync();

        Console.WriteLine($"Loaded {invoices.Count} invoices with all items in 1 single roundtrip.");
    }

    // 2. EXPLICIT LOADING: Nạp bổ sung chủ động chỉ khi thỏa mãn điều kiện nghiệp vụ
    public static async Task LoadWithExplicitLoadingAsync(AppDbContext db, Guid invoiceId)
    {
        var invoice = await db.Invoices.FindAsync(invoiceId);
        if (invoice != null && invoice.RequiresDetailedAudit)
        {
            // Nạp tường minh collection con chỉ khi thực sự cần thiết
            await db.Entry(invoice)
                .Collection(i => i.Items)
                .LoadAsync();
        }
    }
}

public sealed class Invoice { public Guid Id { get; set; } public bool RequiresDetailedAudit { get; set; } public List<InvoiceItem> Items { get; set; } = []; }
public sealed class InvoiceItem { public Guid Id { get; set; } public Product? Product { get; set; } }

