// C# 12 / .NET 8 - Thiết kế DbContext chuyên nghiệp với Fluent API và Audit Interceptor
using System;
using System.Threading;
using System.Threading.Tasks;
using Microsoft.EntityFrameworkCore;

public sealed class CoreBankingDbContext(DbContextOptions<CoreBankingDbContext> options) : DbContext(options)
{
    public DbSet<Account> Accounts => Set<Account>();
    public DbSet<TransactionRecord> Transactions => Set<TransactionRecord>();

    protected override void OnModelCreating(ModelBuilder modelBuilder)
    {
        // Áp dụng cấu hình Fluent API tách biệt theo IEntityTypeConfiguration
        modelBuilder.ApplyConfigurationsFromAssembly(typeof(CoreBankingDbContext).Assembly);
        base.OnModelCreating(modelBuilder);
    }

    // Ghi đè SaveChanges để tự động gán dữ liệu kiểm toán hệ thống (Audit Trail)
    public override Task<int> SaveChangesAsync(CancellationToken cancellationToken = default)
    {
        foreach (var entry in ChangeTracker.Entries<IAuditable>())
        {
            if (entry.State == EntityState.Added)
                entry.Entity.CreatedAtUtc = DateTime.UtcNow;
        }
        return base.SaveChangesAsync(cancellationToken);
    }
}

