using System.Collections.Generic;
using System.Linq;
using System.Threading.Tasks;
using Microsoft.EntityFrameworkCore;

public static class CustomerService
{
    public static async Task LoadRecentVipOrdersAsync(AppDbContext db, Guid customerId)
    {
        // 1. Tải thực thể cha ban đầu (nhanh, gọn, không JOIN)
        var customer = await db.Customers.FindAsync(customerId);
        if (customer is null) return;

        // 2. Chỉ khi thỏa mãn điều kiện nghiệp vụ VIP, mới nạp tường minh đơn hàng
        if (customer.IsVip)
        {
            DateTime thirtyDaysAgo = DateTime.UtcNow.AddDays(-30);

            // Sử dụng Query() để lọc trực tiếp tại SQL Server: Chỉ lấy đơn hàng trong 30 ngày qua
            await db.Entry(customer)
                .Collection(c => c.Orders)
                .Query()
                .Where(o => o.OrderDate >= thirtyDaysAgo && o.TotalAmount > 500m)
                .OrderByDescending(o => o.TotalAmount)
                .LoadAsync(); // Dữ liệu con được tự động gắn vào collection customer.Orders

            Console.WriteLine($"Nạp thành công {customer.Orders.Count} đơn hàng VIP gần đây.");
        }
    }
}

