using Microsoft.EntityFrameworkCore;

public static class UserProfileService
{
    public sealed record UpdateBioRequest(Guid UserId, string NewBio);

    // CÁCH AN TOÀN TUYỆT ĐỐI: Dùng Attach để chỉ UPDATE đúng 1 cột 'Bio'
    public static async Task UpdateBioSafeAsync(AppDbContext db, UpdateBioRequest request)
    {
        // Khởi tạo stub entity chứa đúng Id và dữ liệu mới
        var userStub = new UserAccount { Id = request.UserId, Bio = request.NewBio };

        // Attach đưa entity vào tracker với trạng thái Unchanged (không tạo câu lệnh SQL nào)
        var entry = db.Attach(userStub);

        // Chỉ đánh dấu duy nhất thuộc tính Bio là bị thay đổi
        entry.Property(u => u.Bio).IsModified = true;

        // EF Core sinh chính xác: UPDATE [Users] SET [Bio] = @p0 WHERE [Id] = @p1;
        // Tuyệt đối không chạm vào PasswordHash, Balance hay Email!
        await db.SaveChangesAsync();
    }
}

