// C# 12 / .NET 8 - Tối ưu hóa Batch Processing bằng cách tắt Change Tracking toàn diện
using System;
using System.Collections.Generic;
using System.Linq;
using System.Threading.Tasks;
using Microsoft.EntityFrameworkCore;

public static class DataMigrationEngine
{
    public static async Task ProcessHalfMillionRecordsAsync(AppDbContext db)
    {
        // Tắt toàn diện Change Tracking ở cấp độ context để đạt hiệu năng tối đa
        db.ChangeTracker.QueryTrackingBehavior = QueryTrackingBehavior.NoTracking;
        db.ChangeTracker.AutoDetectChangesEnabled = false;

        int pageSize = 5000;
        int pageIndex = 0;

        while (true)
        {
            // Phân trang stream xử lý từng lô nhỏ, bộ nhớ RAM luôn duy trì phẳng dưới 50MB
            var batch = await db.Invoices
                .OrderBy(x => x.Id)
                .Skip(pageIndex * pageSize)
                .Take(pageSize)
                .Select(x => new { x.Id, x.Amount })
                .ToListAsync();

            if (batch.Count == 0) break;

            // Xử lý dữ liệu ra file stream...
            pageIndex++;
        }
    }
}

// C# 12 / .NET 8 - Production-grade Performance & Correlation ID Middleware
using System;
using System.Diagnostics;
using System.Threading.Tasks;
using Microsoft.AspNetCore.Http;
using Microsoft.Extensions.Logging;

public sealed class RequestPerformanceMiddleware(
    RequestDelegate next,
    ILogger<RequestPerformanceMiddleware> logger)
{
    public async Task InvokeAsync(HttpContext context)
    {
        // 1. Logic thực thi TRƯỚC khi request vào tầng Controller/Endpoint
        string correlationId = context.Request.Headers["X-Correlation-Id"].ToString();
        if (string.IsNullOrWhiteSpace(correlationId))
            correlationId = Guid.NewGuid().ToString("N");

        context.Response.Headers.Append("X-Correlation-Id", correlationId);
        var stopwatch = Stopwatch.StartNew();

        try
        {
            // Chuyển tiếp điều khiển cho Middleware kế tiếp trong Pipeline
            await next(context);
        }
        finally
        {
            // 2. Logic thực thi SAU KHI response quay ngược trở ra ngoài
            stopwatch.Stop();
            long elapsedMs = stopwatch.ElapsedMilliseconds;

            if (elapsedMs > 500) // Cảnh báo nếu request xử lý chậm hơn 500ms
            {
                logger.LogWarning("SLOW REQUEST: {Method} {Path} took {ElapsedMs} ms. CorrelationId: {CorrelationId}",
                    context.Request.Method, context.Request.Path, elapsedMs, correlationId);
            }
        }
    }
}

