var app = builder.Build();

// Model Binding tự động kết hợp từ Header, Route và Custom Parsable Type
app.MapPost("/api/payments/{transactionId:guid}", (
    [FromRoute] Guid transactionId,
    [FromHeader(Name = "X-Signature")] string signature,
    [FromBody] PaymentPayload payload,
    [FromQuery] SortOrder sort) =>
{
    return Results.Ok(new { transactionId, signature, payload, sort });
});

public sealed record PaymentPayload(decimal Amount, string Currency);

// Triển khai IParsable<T> để Model Binding tự động phân giải từ Query String với 0 overhead
public readonly record struct SortOrder(string Column, bool IsAscending) : IParsable<SortOrder>
{
    public static SortOrder Parse(string s, IFormatProvider? provider) =>
        TryParse(s, provider, out var result) ? result : throw new FormatException();

    public static bool TryParse(string? s, IFormatProvider? provider, out SortOrder result)
    {
        if (string.IsNullOrWhiteSpace(s)) { result = default; return false; }
        var parts = s.Split(':');
        result = new SortOrder(parts[0], parts.Length > 1 && parts[1].Equals("asc", StringComparison.OrdinalIgnoreCase));
        return true;
    }
}

