public static class SafeBackgroundDispatcher
{
    public static void DispatchReportGeneration(HttpContext context, ILogger logger)
    {
        // NGUY HIỂM: Không bao giờ truyền trực tiếp biến 'context' vào Task.Run!
        // CHUẨN MỰC: Trích xuất toàn bộ dữ liệu cần thiết thành một DTO/Record bất biến TRƯỚC
        string userId = context.User.FindFirstValue(ClaimTypes.NameIdentifier) ?? "Anonymous";
        string userIp = context.Connection.RemoteIpAddress?.ToString() ?? "Unknown";

        _ = Task.Run(async () =>
        {
            // Background thread chạy hoàn toàn độc lập và an toàn với dữ liệu đã snapshot
            await Task.Delay(1000); // Giả lập tác vụ nặng
            logger.LogInformation("Generating report for User: {UserId} from IP: {UserIp}", userId, userIp);
        });
    }
}

