// C# 12 / .NET 8 - Cấu hình Kubernetes Probes chuẩn Cloud-Native
using System;
using System.Threading;
using System.Threading.Tasks;
using Microsoft.AspNetCore.Builder;
using Microsoft.AspNetCore.Diagnostics.HealthChecks;
using Microsoft.Extensions.DependencyInjection;
using Microsoft.Extensions.Diagnostics.HealthChecks;

var builder = WebApplication.CreateBuilder(args);

// Đăng ký Health Checks và các kiểm tra phụ thuộc cụ thể
builder.Services.AddHealthChecks()
    .AddCheck("self", () => HealthCheckResult.Healthy(), tags: ["liveness"])
    .AddCheck<DatabaseHealthCheck>("sql_database", tags: ["readiness"]);

var app = builder.Build();

// 1. Liveness Endpoint: Chỉ kiểm tra tiến trình có sống không (restart nếu deadlock)
app.MapHealthChecks("/health/live", new HealthCheckOptions
{
    Predicate = check => check.Tags.Contains("liveness")
});

// 2. Readiness Endpoint: Kiểm tra kết nối tới DB, Cache (cô lập khỏi load balancer nếu lỗi)
app.MapHealthChecks("/health/ready", new HealthCheckOptions
{
    Predicate = check => check.Tags.Contains("readiness")
});

app.Run();

// Custom Check kiểm tra khả năng kết nối Database
public sealed class DatabaseHealthCheck : IHealthCheck
{
    public async Task<HealthCheckResult> CheckHealthAsync(HealthCheckContext context, CancellationToken ct = default)
    {
        try
        {
            // Giả lập lệnh ping database nhẹ: SELECT 1;
            await Task.Delay(10, ct);
            return HealthCheckResult.Healthy("Database kết nối ổn định.");
        }
        catch (Exception ex)
        {
            return HealthCheckResult.Unhealthy("Mất kết nối Database!", ex);
        }
    }
}

