// 1. Đăng ký nhiều triển khai của cùng interface với các khóa định danh riêng biệt
builder.Services.AddKeyedScoped<IPaymentGateway, VnpayPaymentGateway>("vnpay");
builder.Services.AddKeyedScoped<IPaymentGateway, MomoPaymentGateway>("momo");

var app = builder.Build();

// 2. Inject chính xác implementation cần thiết thông qua [FromKeyedServices]
app.MapPost("/api/checkout/{provider}", async (
    string provider,
    decimal amount,
    IServiceProvider sp) =>
{
    // Phân giải động tại runtime dựa trên tham số người dùng gửi lên
    var gateway = sp.GetKeyedService<IPaymentGateway>(provider.ToLowerInvariant());
    if (gateway is null)
        return Results.BadRequest($"Cổng thanh toán '{provider}' không được hỗ trợ.");

    bool success = await gateway.ProcessChargeAsync(amount);
    return Results.Ok(new { Provider = provider, Success = success });
});

app.Run();

public interface IPaymentGateway { Task<bool> ProcessChargeAsync(decimal amount); }
public sealed class VnpayPaymentGateway : IPaymentGateway { public Task<bool> ProcessChargeAsync(decimal amount) => Task.FromResult(true); }
public sealed class MomoPaymentGateway : IPaymentGateway { public Task<bool> ProcessChargeAsync(decimal amount) => Task.FromResult(true); }

