// C# 12 / .NET 8 - Xử lý Multicast Delegate an toàn, chống Short-circuit Exception
using System;

public sealed class PaymentDispatcher
{
    // Khai báo Delegate chuẩn mực
    public delegate void PaymentProcessedHandler(Guid transactionId, decimal amount);

    public event PaymentProcessedHandler? OnPaymentProcessed;

    public void DispatchEvent(Guid transactionId, decimal amount)
    {
        if (OnPaymentProcessed is null) return;

        // Lấy danh sách toàn bộ các delegate đã đăng ký
        Delegate[] subscribers = OnPaymentProcessed.GetInvocationList();

        foreach (PaymentProcessedHandler handler in subscribers)
        {
            try
            {
                // Thực thi từng subscriber độc lập; lỗi của subscriber này không ảnh hưởng người khác
                handler(transactionId, amount);
            }
            catch (Exception ex)
            {
                Console.WriteLine($"[ERROR] Subscriber {handler.Method.Name} gặp lỗi: {ex.Message}");
            }
        }
    }
}

// C# 12 / .NET 8 - Standard Dispose Pattern hoàn chỉnh kết hợp IAsyncDisposable
using System;
using System.IO;
using System.Threading.Tasks;

public class EnterpriseResourceHolder : IDisposable, IAsyncDisposable
{
    private FileStream? _fileStream;
    private bool _disposed;

    public EnterpriseResourceHolder(string path)
    {
        _fileStream = new FileStream(path, FileMode.OpenOrCreate);
    }

    // 1. Dispose đồng bộ: Dọn dẹp xác định, giải phóng handle ngay lập tức
    public void Dispose()
    {
        Dispose(disposing: true);
        // QUAN TRỌNG NHẤT: Ngăn GC đẩy đối tượng vào Finalizer Queue, tránh sống sót lên Gen 1/2
        GC.SuppressFinalize(this);
    }

    // 2. Dispose bất đồng bộ cho tài nguyên I/O hiện đại (.NET 8)
    public async ValueTask DisposeAsync()
    {
        if (_fileStream != null)
        {
            await _fileStream.DisposeAsync();
            _fileStream = null;
        }
        Dispose(disposing: false);
        GC.SuppressFinalize(this);
    }

    protected virtual void Dispose(bool disposing)
    {
        if (_disposed) return;

        if (disposing)
        {
            // Giải phóng các Managed Resources khác
            _fileStream?.Dispose();
            _fileStream = null;
        }

        // Giải phóng Unmanaged Resources (nếu có: con trỏ C, IntPtr...)
        _disposed = true;
    }

    // Finalizer: Chỉ đóng vai trò lưới an toàn cuối cùng nếu lập trình viên quên gọi Dispose
    ~EnterpriseResourceHolder() => Dispose(disposing: false);
}

// C# 12 / .NET 8 - Zero-Copy High-Performance Computing với 'in', 'ref', 'out'
using System;

// Bắt buộc là 'readonly struct' để triệt tiêu hoàn toàn Defensive Copying khi dùng 'in'
public readonly struct Matrix4x4(float m11, float m22, float m33, float m44)
{
    public readonly float M11 = m11, M22 = m22, M33 = m33, M44 = m44;
}

public static class MathEngine
{
    // 1. 'in': Truyền tham chiếu chỉ đọc cho struct 64 bytes -> 0 byte copy overhead
    public static float ComputeDeterminant(in Matrix4x4 matrix)
    {
        // matrix.M11 = 5f; // LỖI BIÊN DỊCH: 'in' cấm sửa đổi trạng thái!
        return matrix.M11 * matrix.M22 * matrix.M33 * matrix.M44;
    }

    // 2. 'ref': Đọc và biến đổi trực tiếp trên vùng nhớ gốc của caller
    public static void InvertInPlace(ref Matrix4x4 matrix)
    {
        matrix = new Matrix4x4(-matrix.M11, -matrix.M22, -matrix.M33, -matrix.M44);
    }

    // 3. 'out': Cam kết khởi tạo giá trị mới trả về cho caller
    public static bool TryParseMatrix(string input, out Matrix4x4 result)
    {
        if (string.IsNullOrWhiteSpace(input))
        {
            result = default; // Bắt buộc phải gán trước khi return false
            return false;
        }
        result = new Matrix4x4(1, 1, 1, 1);
        return true;
    }
}

// C# 12 / .NET 8 - Đối chiếu hành vi giữa override (Đa hình) vs new (Che giấu)
using System;

public class BaseAccount
{
    // Virtual cho phép lớp con ghi đè đa hình
    public virtual void CalculateInterest() => Console.WriteLine("Base Account Interest: 1%");
    public virtual void PrintStatement() => Console.WriteLine("Base Statement");
}

public sealed class PremiumAccount : BaseAccount
{
    // 1. OVERRIDE: Thay thế slot vtable - Đa hình động chuẩn mực
    public override void CalculateInterest() => Console.WriteLine("Premium Account Interest: 5%");

    // 2. NEW: Method Hiding - Cắt đứt quan hệ đa hình, tạo slot mới riêng biệt
    public new void PrintStatement() => Console.WriteLine("Premium Customized Statement");
}

public static class PolymorphismDemo
{
    public static void Run()
    {
        PremiumAccount concrete = new();
        BaseAccount polymorphed = concrete; // Ép kiểu về lớp cha

        // KẾT QUẢ VỚI OVERRIDE:
        polymorphed.CalculateInterest(); // In: 'Premium Account Interest: 5%' -> ĐA HÌNH HOẠT ĐỘNG HOÀN HẢO

        // KẾT QUẢ VỚI NEW (CẠM BẪY):
        polymorphed.PrintStatement();    // In: 'Base Statement' -> LỚP CHA CHẠY, METHOD CON BỊ BỎ RƠI!
        concrete.PrintStatement();       // In: 'Premium Customized Statement'
    }
}

// C# 12 / .NET 8 - Gọi song song với Task.WhenAll và Thu thập 100% Exceptions
using System;
using System.Collections.Generic;
using System.Threading.Tasks;

public static class ParallelApiAggregator
{
    public static async Task AggregateUserDataAsync()
    {
        // Kích hoạt đồng thời cả 3 task độc lập (Fan-out)
        Task<string> task1 = CallServiceAsync("CreditScore", shouldFail: true);
        Task<string> task2 = CallServiceAsync("FraudCheck", shouldFail: true);
        Task<string> task3 = CallServiceAsync("BalanceSummary", shouldFail: false);

        var allTasks = Task.WhenAll(task1, task2, task3);

        try
        {
            await allTasks; // Cú pháp await này chỉ rethrow exception ĐẦU TIÊN!
            Console.WriteLine("Tất cả service hoàn thành mỹ mãn.");
        }
        catch (Exception)
        {
            // BẮT BUỘC: Truy cập trực tiếp vào allTasks.Exception để lấy trọn vẹn danh sách lỗi
            if (allTasks.Exception != null)
            {
                AggregateException flattened = allTasks.Exception.Flatten();
                Console.WriteLine($"Tổng số lỗi phát hiện: {flattened.InnerExceptions.Count}");

                foreach (var innerEx in flattened.InnerExceptions)
                {
                    Console.WriteLine($"[LOGGED ERROR] {innerEx.Message}");
                }
            }
        }
    }

    private static async Task<string> CallServiceAsync(string name, bool shouldFail)
    {
        await Task.Delay(50); // Giả lập độ trễ mạng
        if (shouldFail) throw new HttpRequestException($"Service {name} timeout hoặc từ chối kết nối!");
        return $"{name} Data OK";
    }
}

