using System;
using System.Collections.Generic;
using System.Linq;

public static class EnumerationPitfallDemo
{
    // Iterator method có side-effect thực thi mỗi khi được duyệt
    private static IEnumerable<int> GenerateDataStream()
    {
        for (int i = 1; i <= 3; i++)
        {
            Console.WriteLine($"--> Cấp phát và tính toán phần tử {i} (Tốn I/O)");
            yield return i;
        }
    }

    public static void ExecuteAntipattern()
    {
        IEnumerable<int> stream = GenerateDataStream();

        // DUYỆT LẦN 1: Kiểm tra có phần tử nào không
        bool hasData = stream.Any(); 
        Console.WriteLine($"Có dữ liệu không: {hasData}");

