// C# 12 / .NET 8 - Chuẩn mực sử dụng DbContext an toàn bên trong BackgroundService
using System;
using System.Threading;
using System.Threading.Tasks;
using Microsoft.EntityFrameworkCore;
using Microsoft.Extensions.DependencyInjection;
using Microsoft.Extensions.Hosting;
using Microsoft.Extensions.Logging;

public sealed class OrderCleanupBackgroundService(
    IServiceScopeFactory scopeFactory, // INJECT ScopeFactory THAY VÌ DbContext trực tiếp!
    ILogger<OrderCleanupBackgroundService> logger) : BackgroundService
{
    protected override async Task ExecuteAsync(CancellationToken stoppingToken)
    {
        logger.LogInformation("Order Cleanup Service bắt đầu hoạt động.");
        var timer = new PeriodicTimer(TimeSpan.FromSeconds(10));

        while (await timer.WaitForNextTickAsync(stoppingToken))
        {
            try
            {
                // TẠO SCOPE MỚI CHO TỪNG CHU KỲ: Tự động Dispose DbContext và giải phóng kết nối DB
                using (var scope = scopeFactory.CreateScope())
                {
                    var db = scope.ServiceProvider.GetRequiredService<AppDbContext>();

                    DateTime cutoff = DateTime.UtcNow.AddMinutes(-30);
                    int deletedCount = await db.Orders
                        .Where(o => o.Status == "PENDING" && o.CreatedAt < cutoff)
                        .ExecuteDeleteAsync(stoppingToken); // .NET 8 Bulk Delete cực nhanh

                    if (deletedCount > 0)
                        logger.LogInformation("Đã dọn dẹp thành công {Count} đơn hàng quá hạn.", deletedCount);
                }
            }
            catch (Exception ex) when (ex is not OperationCanceledException)
            {
                logger.LogError(ex, "Lỗi xảy ra trong chu kỳ dọn dẹp đơn hàng.");
            }
        }
    }
}

