// C# 12 / .NET 8 - Khắc phục Cartesian Explosion bằng AsSplitQuery trong EF Core
using System;
using System.Collections.Generic;
using System.Linq;
using System.Threading.Tasks;
using Microsoft.EntityFrameworkCore;

public static class OrderQueryOptimizationService
{
    public static async Task<OrderAggregate?> GetOrderDetailsOptimizedAsync(AppDbContext db, Guid orderId)
    {
        // AsSplitQuery() chỉ đạo EF Core sinh ra 3 câu lệnh SELECT riêng biệt:
        // 1. SELECT * FROM Orders WHERE Id = @id
        // 2. SELECT * FROM OrderItems WHERE OrderId = @id
        // 3. SELECT * FROM ShippingLogs WHERE OrderId = @id
        // Triệt tiêu 100% hiện tượng bùng nổ dữ liệu nhân chéo
        return await db.Orders
            .AsNoTracking()
            .AsSplitQuery() // GIẢI PHÁP VÀNG: Ngăn chặn Cartesian Explosion
            .Include(o => o.Items)
            .Include(o => o.ShippingLogs)
            .FirstOrDefaultAsync(o => o.Id == orderId);
    }
}

public sealed class OrderAggregate { public Guid Id { get; set; } public List<OrderItem> Items { get; set; } = []; public List<ShippingLog> ShippingLogs { get; set; } = []; }
