using Microsoft.Extensions.Logging;

public static class DiagnosticConfigurator
{
    public static void ConfigureLoggingAndStrictWarnings(DbContextOptionsBuilder options)
    {
        options
            // 1. Ghi log SQL rõ ràng kèm tham số trong môi trường Debug
            .LogTo(Console.WriteLine, [DbLoggerCategory.Database.Command.Name], LogLevel.Information)
            .EnableSensitiveDataLogging()

            // 2. Chuyển đổi các cảnh báo tiềm ẩn N+1 thành Exception ngay lập tức khi test
