                .Throw(CoreEventId.LazyLoadOnDisposedContextWarning)
                .Log(CoreEventId.DetachedLazyLoadingWarning));
    }
}

// C# 12 / .NET 8 - Đối chiếu Bảo mật giữa FromSql vs Lỗ hổng SQL Injection của FromSqlRaw
using System;
using System.Collections.Generic;
using System.Threading.Tasks;
using Microsoft.Data.SqlClient;
using Microsoft.EntityFrameworkCore;

public static class RawSqlSecurityDemo
{
    // 1. CHUẨN MỰC AN TOÀN (C# 12 / .NET 8): FromSql tự động tham số hóa qua FormattableString
    public static async Task<List<User>> SearchSafeAsync(AppDbContext db, string userInput)
    {
        // Dù userInput có chứa mã độc: "admin' OR '1'='1", EF Core vẫn chuyển thành: 
        // SELECT * FROM Users WHERE UserName = @p0
        // An toàn tuyệt đối 100%!
        return await db.Users
            .FromSql($"SELECT * FROM Users WHERE UserName = {userInput}")
            .ToListAsync();
    }

    // 2. NGUY HIỂM CHẾT NGƯỜI: Lỗ hổng SQL Injection với FromSqlRaw
    public static async Task<List<User>> VulnerableSearchAsync(AppDbContext db, string userInput)
    {
        // NGUY CƠ BỊ TẤN CÔNG: Nối chuỗi nội suy trực tiếp vào string thô
        #pragma warning disable EF1000
        return await db.Users
            .FromSqlRaw($"SELECT * FROM Users WHERE UserName = '{userInput}'") // LỖ HỔNG LỚN!
            .ToListAsync();
        #pragma warning restore EF1000
    }

    // 3. NẾU BẮT BUỘC DÙNG FromSqlRaw: Phải truyền DbParameter tường minh
    public static async Task<List<User>> SafeFromSqlRawAsync(AppDbContext db, string userInput)
    {
        var parameter = new SqlParameter("@userName", userInput);
        return await db.Users
            .FromSqlRaw("SELECT * FROM Users WHERE UserName = @userName", parameter)
            .ToListAsync();
    }
}

public sealed class User { public Guid Id { get; set; } public string UserName { get; set; } = ""; }

// C# 12 / .NET 8 - Bulk Update 100.000 bản ghi siêu tốc với ExecuteUpdateAsync
using System;
using System.Linq;
using System.Threading.Tasks;
using Microsoft.EntityFrameworkCore;

public static class BatchSettlementService
{
    public static async Task<int> MarkOverdueInvoicesAsBadDebtAsync(AppDbContext db)
    {
        DateTime ninetyDaysAgo = DateTime.UtcNow.AddDays(-90);

        // Dịch thẳng thành 1 câu SQL UPDATE duy nhất trên Database Engine:
        // UPDATE [Invoices] SET [Status] = 'BAD_DEBT', [UpdatedAtUtc] = @now WHERE [Status] = 'PENDING' AND [DueDate] < @ninetyDaysAgo
        // Không load bất kỳ bản ghi nào về RAM! Hoàn thành trong 50ms!
        int affectedRows = await db.Invoices
            .Where(i => i.Status == "PENDING" && i.DueDate < ninetyDaysAgo)
            .ExecuteUpdateAsync(setter => setter
                .SetProperty(i => i.Status, "BAD_DEBT")
                .SetProperty(i => i.UpdatedAtUtc, DateTime.UtcNow));

        Console.WriteLine($"Đã cập nhật thành công {affectedRows} hóa đơn sang nợ xấu.");
        return affectedRows;
