// Triển khai IExceptionHandler chuẩn mực trong .NET 8
public sealed class GlobalExceptionHandler(
    IProblemDetailsService problemDetailsService,
    ILogger<GlobalExceptionHandler> logger) : IExceptionHandler
{
    public async ValueTask<bool> TryHandleAsync(
        HttpContext httpContext, 
        Exception exception, 
        CancellationToken cancellationToken)
    {
        string traceId = Activity.Current?.Id ?? httpContext.TraceIdentifier;
        logger.LogError(exception, "Unhandled Exception xảy ra. TraceId: {TraceId}", traceId);

        // Thiết lập mã HTTP Status tương ứng với loại Exception
        int statusCode = exception switch
        {
            ArgumentException => StatusCodes.Status400BadRequest,
            KeyNotFoundException => StatusCodes.Status404NotFound,
            _ => StatusCodes.Status500InternalServerError
        };

        httpContext.Response.StatusCode = statusCode;

        // Trả về JSON ProblemDetails chuẩn RFC 7807
        return await problemDetailsService.TryWriteAsync(new ProblemDetailsContext
        {
            HttpContext = httpContext,
            ProblemDetails = new Microsoft.AspNetCore.Mvc.ProblemDetails
            {
                Status = statusCode,
                Title = "Đã xảy ra lỗi trong quá trình xử lý yêu cầu.",
                Detail = httpContext.RequestServices.GetRequiredService<IHostEnvironment>().IsDevelopment() 
                    ? exception.Message 
                    : "Vui lòng liên hệ bộ phận hỗ trợ kèm mã kiểm soát (TraceId).",
                Instance = httpContext.Request.Path,
                Extensions = { ["traceId"] = traceId }
            }
        });
    }
}

