// C# 12 / .NET 8 - Tối ưu hóa Zero-Allocation Caching Layer với ValueTask<T>
using System;
using System.Collections.Concurrent;
using System.Threading.Tasks;

public sealed class HighPerformanceCacheGateway
{
    private readonly ConcurrentDictionary<string, byte[]> _memoryCache = new();

    // 98% trường hợp trúng Cache -> Trả về ngay lập tức với 0 BYTE CẤP PHÁT TRÊN HEAP!
    public ValueTask<byte[]> GetPayloadAsync(string key)
    {
        if (_memoryCache.TryGetValue(key, out var cachedData))
        {
            // Trả về trực tiếp Value Type Struct, hoàn toàn không tạo Task object trên Heap
            return new ValueTask<byte[]>(cachedData);
        }

        // 2% trường hợp trượt Cache -> Gọi tác vụ I/O mạng nặng nề
        return new ValueTask<byte[]>(FetchFromRemoteStorageAsync(key));
    }

    private async Task<byte[]> FetchFromRemoteStorageAsync(string key)
    {
        await Task.Delay(50); // Giả lập độ trễ mạng
        byte[] data = [0xDE, 0xAD, 0xBE, 0xEF];
        _memoryCache[key] = data;
        return data;
    }
}

