public static class UltraOptimizedQueryService
{
    // 1. Biên dịch sẵn câu truy vấn thành Delegate tĩnh: Triệt tiêu chi phí parse LINQ Expression Tree
    private static readonly Func<AppDbContext, decimal, IAsyncEnumerable<OrderSummaryDto>> CompiledTopOrdersQuery =
        EF.CompileAsyncQuery((AppDbContext db, decimal minAmount) =>
            db.Orders
                .AsNoTracking()
                .Where(o => o.TotalAmount >= minAmount)
                .OrderByDescending(o => o.TotalAmount)
                .Take(20)
                // Projection chính xác: Database chỉ đọc các cột trong Covering Index
                .Select(o => new OrderSummaryDto(o.Id, o.TotalAmount, o.CreatedAtUtc)));

    public static async Task<List<OrderSummaryDto>> GetTopOrdersFastAsync(AppDbContext db, decimal threshold)
    {
        var results = new List<OrderSummaryDto>(20);
        await foreach (var item in CompiledTopOrdersQuery(db, threshold))
        {
            results.Add(item);
        }
        return results;
    }
}

