// C# 12 / .NET 8 - Xử lý Xung đột Đồng thời Lạc quan với Thuật toán Retry và Merge
using System;
using System.Threading.Tasks;
using Microsoft.EntityFrameworkCore;

public static class ConcurrencyResolutionEngine
{
    public static async Task<bool> UpdateAccountBalanceWithRetryAsync(
        AppDbContext db, 
        Guid accountId, 
        decimal depositAmount, 
        int maxRetries = 3)
    {
        for (int attempt = 1; attempt <= maxRetries; attempt++)
        {
            try
            {
                var account = await db.Accounts.FindAsync(accountId);
                if (account is null) return false;

                account.Balance += depositAmount;
                account.LastUpdatedUtc = DateTime.UtcNow;

                await db.SaveChangesAsync();
                return true; // Cập nhật thành công!
            }
            catch (DbUpdateConcurrencyException ex)
            {
                if (attempt == maxRetries) throw; // Vượt quá số lần thử lại

                // LẤY DỮ LIỆU MỚI NHẤT TỪ DATABASE ĐỂ MERGE LẠI NGHIỆP VỤ
                var entry = ex.Entries[0];
                var databaseValues = await entry.GetDatabaseValuesAsync();
                if (databaseValues is null)
                {
                    // Bản ghi đã bị xóa bởi giao dịch khác
                    return false;
                }

                // Cập nhật lại giá trị gốc (OriginalValues) của tracker bằng dữ liệu DB mới
                entry.OriginalValues.SetValues(databaseValues);
                // Tiếp tục vòng lặp retry tiếp theo...
            }
        }
        return false;
    }
}

