// C# 12 / .NET 8 - Tự động hóa FluentValidation bằng MediatR Pipeline Behavior
using System;
using System.Collections.Generic;
using System.Linq;
using System.Threading;
using System.Threading.Tasks;
using FluentValidation;
using MediatR;

// Pipeline Behavior bắt buộc chạy trước mọi Request
public sealed class ValidationBehavior<TRequest, TResponse>(
    IEnumerable<IValidator<TRequest>> validators) : IPipelineBehavior<TRequest, TResponse>
    where TRequest : notnull
{
    public async Task<TResponse> Handle(
        TRequest request, 
        RequestHandlerDelegate<TResponse> next, 
        CancellationToken cancellationToken)
    {
        if (validators.Any())
        {
            var context = new ValidationContext<TRequest>(request);

            // Chạy song song tất cả các bộ validate đã đăng ký trong DI
            var validationResults = await Task.WhenAll(
                validators.Select(v => v.ValidateAsync(context, cancellationToken)));

            var failures = validationResults
                .SelectMany(r => r.Errors)
                .Where(f => f != null)
                .ToList();

            // Ném exception ngay lập tức nếu dữ liệu không hợp lệ (Fail-fast)
            if (failures.Count != 0)
                throw new ValidationException(failures);
        }

        // Chuyển tiếp sang Behavior tiếp theo hoặc tới chính Handler
        return await next();
    }
}

