// C# 12 / .NET 8 - Tối ưu hóa Reflection: Chuyển đổi sang Compiled Expression Tree Cache
using System;
using System.Collections.Concurrent;
using System.Linq.Expressions;
using System.Reflection;

public static class FastPropertyAccessor
{
    // Cache chứa các compiled delegate có tốc độ thực thi tương đương 100% mã viết tay
    private static readonly ConcurrentDictionary<PropertyInfo, Func<object, object>> GetterCache = new();

    public static object GetFastValue(object target, PropertyInfo propertyInfo)
    {
        var getter = GetterCache.GetOrAdd(propertyInfo, prop =>
        {
            // Xây dựng Expression Tree: (object instance) => (object)((TargetType)instance).PropertyName
            var instanceParam = Expression.Parameter(typeof(object), "instance");
            var castInstance = Expression.Convert(instanceParam, prop.DeclaringType!);
            var propertyAccess = Expression.Property(castInstance, prop);
            var castResult = Expression.Convert(propertyAccess, typeof(object));

            // Biên dịch thành CIL Delegate Native trong bộ nhớ
            return Expression.Lambda<Func<object, object>>(castResult, instanceParam).Compile();
        });

        return getter(target); // Tốc độ nhanh gấp 80 lần MethodInfo.GetValue()!
    }
}

// C# 12 / .NET 8 - Sức mạnh của Exception Filter (when) trong Điều tra Sự cố Production
using System;
using System.Net.Http;

public static class ResilientHttpExecutor
{
    public static void ExecuteApiCallWithFilter()
    {
        try
        {
            SimulateFailingCall();
        }
        // CHUẨN MỰC SENIOR: Exception Filter đánh giá điều kiện TRƯỚC KHI tháo dỡ stack
        catch (HttpRequestException ex) when (ex.StatusCode == System.Net.HttpStatusCode.ServiceUnavailable)
        {
            // Khối này CHỈ bắt lỗi 503 để Retry
            Console.WriteLine("Server quá tải 503, đang chuẩn bị Retry...");
        }
        // Nếu là lỗi 401 hoặc 404, CLR hoàn toàn bỏ qua khối catch trên, Stack KHÔNG BỊ THÁO DỠ,
        // bảo toàn toàn bộ hiện trường Call Stack cho các công cụ giám sát (APM, Crash Dump)!
    }

    // ANTIPATTERN KINH ĐIỂN CẦN TRÁNH:
    public static void BadExceptionHandling()
    {
        try
        {
            SimulateFailingCall();
        }
        catch (HttpRequestException ex)
        {
            // TẠI ĐÂY: Stack đã bị tháo dỡ (Unwound)! Mất sạch biến cục bộ của SimulateFailingCall!
            if (ex.StatusCode != System.Net.HttpStatusCode.ServiceUnavailable)
            {
                throw; // Rethrow này làm sai lệch Call Stack trong Crash Dump!
            }
        }
    }

    private static void SimulateFailingCall() => 
        throw new HttpRequestException("Unauthorized", null, System.Net.HttpStatusCode.Unauthorized);
}

// C# 12 / .NET 8 - Sử dụng Memory<T> cho Async Pipeline và Span<T> cho Tính toán Đồng bộ
using System;
using System.IO;
using System.Threading.Tasks;

public static class HighPerformanceDataStreamParser
{
    // 1. Dùng Memory<T> khi cần truyền dữ liệu qua các điểm 'await' bất đồng bộ
    public static async Task ProcessNetworkPacketAsync(Stream stream, Memory<byte> buffer)
    {
        // Memory<T> an toàn tuyệt đối khi nằm trên Heap của Async State Machine
        int bytesRead = await stream.ReadAsync(buffer);

        // Khi bắt đầu tính toán đồng bộ trong cùng 1 stack frame: Chuyển sang Span để đạt tốc độ tối đa!
        ReadOnlySpan<byte> dataSpan = buffer.Span.Slice(0, bytesRead);
        ParsePacketPayload(dataSpan);
    }

    // 2. Dùng Span<T> cho các hàm xử lý tính toán đồng bộ thuần túy (Zero Heap Allocation)
    public static void ParsePacketPayload(ReadOnlySpan<byte> packet)
    {
        if (packet.Length < 4) return;

        // Cắt lát (Slice) tức thì, 0 byte GC allocation, tốc độ tương đương con trỏ C++
        ReadOnlySpan<byte> header = packet[..4];
        ReadOnlySpan<byte> payload = packet[4..];

        Console.WriteLine($"Header size: {header.Length}, Payload size: {payload.Length}");
    }
}

// C# 12 / .NET 8 - Code mẫu thiết lập Cảnh báo Thread Pool Starvation tự động trong Ứng dụng
using System;
using System.Threading;
using System.Threading.Tasks;
using Microsoft.Extensions.Hosting;
using Microsoft.Extensions.Logging;

public sealed class ThreadPoolHealthMonitor(ILogger<ThreadPoolHealthMonitor> logger) : BackgroundService
{
    protected override async Task ExecuteAsync(CancellationToken stoppingToken)
    {
        var timer = new PeriodicTimer(TimeSpan.FromSeconds(2));

        while (await timer.WaitForNextTickAsync(stoppingToken))
        {
            ThreadPool.GetAvailableThreads(out int availableWorker, out int availableIocp);
            ThreadPool.GetMaxThreads(out int maxWorker, out int maxIocp);

            int busyWorkerThreads = maxWorker - availableWorker;
            long pendingWorkItems = ThreadPool.PendingWorkItemCount; // Chỉ số vàng (.NET 6+)

            // Nếu có công việc tồn đọng trong hàng đợi nhưng số luồng rảnh rỗi quá ít -> STARVATION CẢNH BÁO!
            if (pendingWorkItems > 50)
            {
                logger.LogCritical(
                    "[THREADPOOL STARVATION DETECTED] Pending Work Items: {Pending}, Busy Threads: {Busy}, Available: {Avail}",
                    pendingWorkItems, busyWorkerThreads, availableWorker);
            }
        }
    }
}

// C# 12 / .NET 8 - Giải pháp Tái sử dụng Business Logic trong IQueryable thông qua Expression Tree
using System;
using System.Linq;
using System.Linq.Expressions;
using System.Threading.Tasks;
using Microsoft.EntityFrameworkCore;

public sealed class OrderEntity
{
    public Guid Id { get; set; }
    public string Status { get; set; } = "";
    public decimal TotalAmount { get; set; }
    public DateTime CreatedAtUtc { get; set; }

    // 1. SAI LẦM: Viết method thông thường -> Ném InvalidOperationException khi dùng trong IQueryable!
    // public bool IsValidOrder() => Status == "COMPLETED" && TotalAmount > 100m;

    // 2. CHUẨN MỰC KIẾN TRÚC: Định nghĩa biểu thức dưới dạng Expression Tree có thể dịch 100% sang SQL
    public static Expression<Func<OrderEntity, bool>> IsValidOrderExpression =>
        order => order.Status == "COMPLETED" && order.TotalAmount > 100m;
}

public static class OrderQueryService
{
    public static async Task<System.Collections.Generic.List<OrderEntity>> GetValidOrdersAsync(AppDbContext db)
    {
        // Dịch 100% sang SQL chuẩn: SELECT * FROM Orders WHERE Status = 'COMPLETED' AND TotalAmount > 100.0
        return await db.Orders
            .AsNoTracking()
            .Where(OrderEntity.IsValidOrderExpression) // Hoạt động hoàn hảo, không có ngoại lệ!
            .ToListAsync();
    }
}

// C# 12 / .NET 8 - Streaming Dữ liệu Lớn với IAsyncEnumerable và [EnumeratorCancellation]
using System;
using System.Collections.Generic;
using System.Runtime.CompilerServices;
using System.Threading;
using System.Threading.Tasks;
using Microsoft.AspNetCore.Builder;
using Microsoft.AspNetCore.Http;

var builder = WebApplication.CreateBuilder(args);
var app = builder.Build();

// Minimal API tự động stream JSON từng phần tử (NDJSON hoặc Chunked Transfer) về client
app.MapGet("/api/transactions/stream", (CancellationToken requestAborted) =>
{
    return TransactionStreamEngine.StreamLargeReportAsync(requestAborted);
});

app.Run();

public static class TransactionStreamEngine
{
    // ASYNC STREAMING CHUẨN MỰC: Bộ nhớ RAM luôn duy trì phẳng dưới vài KB dù stream hàng triệu dòng
    public static async IAsyncEnumerable<TransactionRecord> StreamLargeReportAsync(
        [EnumeratorCancellation] CancellationToken cancellationToken = default)
    {
        for (int i = 1; i <= 100_000; i++)
        {
            // Kiểm tra tín hiệu hủy bỏ trước mỗi lần đọc dòng mới
            cancellationToken.ThrowIfCancellationRequested();

            // Giả lập đọc bất đồng bộ từng dòng từ Database Reader
            await Task.Delay(5, cancellationToken);

            // Bắn dữ liệu về client ngay lập tức mà không giữ lại trong RAM máy chủ
            yield return new TransactionRecord(Guid.NewGuid(), 150.0m * i, DateTime.UtcNow);
        }
    }
}

public readonly record struct TransactionRecord(Guid Id, decimal Amount, DateTime CreatedAtUtc);
